owned=set(["src/canvaspilot/api.py","src/canvaspilot/cli.py","src/canvaspilot/mcp_server.py","src/canvaspilot/bundle.py","src/canvaspilot/discussion_thread.py","tests/test_discussion_thread.py","tests/test_discussion_thread_native.py","docs/DISCUSSIONS.md","README.md"])
def sha(raw):
    return hashlib.sha256(raw).hexdigest()
def blob(raw):
    return hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\\0"+raw).hexdigest()
# Use the actual Git object NUL rather than the escaped text in JSON receipts.
def git_blob(raw):
    return hashlib.sha1(b"blob "+str(len(raw)).encode()+bytes([0])+raw).hexdigest()
rows=[]
for path,pin in expected.items():
    old=(root/"baseline"/path).read_bytes()
    new=(root/"candidate"/path).read_bytes()
    assert git_blob(old)==pin["git_blob"] and sha(old)==pin["sha256"], path
    if path not in owned:
        assert new==old,path
    rows.append({"path":path,"baseline_git_blob":git_blob(old),"baseline_sha256":sha(old),"candidate_git_blob":git_blob(new),"candidate_sha256":sha(new),"unchanged":old==new,"bytes":len(new)})
functions={}
for path, ignored in (("src/canvaspilot/api.py", {"CanvasAPI.discussion_thread"}),("src/canvaspilot/mcp_server.py",{"canvas_discussion_thread"})):
    def collect(text):
        found={}
        def walk(items,prefix=""):
            for item in items:
                if isinstance(item,ast.ClassDef):
                    walk(item.body,prefix+item.name+".")
                elif isinstance(item,(ast.FunctionDef,ast.AsyncFunctionDef)):
                    found[prefix+item.name]=ast.dump(item,include_attributes=False)
        walk(ast.parse(text).body)
        return found
    old=collect((root/"baseline"/path).read_text())
    new=collect((root/"candidate"/path).read_text())
    assert set(new)-set(old)==ignored,path
    assert all(new[name]==value for name,value in old.items()),path
    functions[path]={"original_function_count":len(old),"original_functions_ast_unchanged":True,"added_functions":sorted(set(new)-set(old))}
seams={}
for path in ("src/canvaspilot/api.py","src/canvaspilot/cli.py","src/canvaspilot/bundle.py","src/canvaspilot/mcp_server.py"):
    old=(root/"baseline"/path).read_text().splitlines(True)
    new=(root/"candidate"/path).read_text().splitlines(True)
    opcodes=difflib.SequenceMatcher(None,old,new,autojunk=False).get_opcodes()
    edits=[{"kind":kind,"before_lines":old[a:b],"after_lines":new[c:d]} for kind,a,b,c,d in opcodes if kind!="equal"]
    for edit in edits:
        if path=="src/canvaspilot/mcp_server.py" and edit["kind"]=="replace":
            assert edit["before_lines"]==["from pydantic import Field, StrictInt\\n"] or edit["before_lines"]==["from pydantic import Field, StrictInt\n"]
            assert edit["after_lines"]==["from pydantic import Field, StrictBool, StrictInt\n"]
        else:
            assert edit["kind"]=="insert",(path,edit)
    seams[path]=edits
